// TestClearSessionState_SerializesAgainstConcurrentMutation is a real
// concurrency reproduction of the race clearSessionState's gate closes:
// before the fix, it acquired no lock at all, so a clear racing a
// concurrently-running MutateSessionState for the same session could run
// while that mutation was still in flight -- deleting the state file out
// from under a write that had not yet landed, silently destroying it. This
// drives both paths with real goroutines and explicit channel
// synchronization (no sleeps to fake a race): a writer goroutine holds the
// real gate (via MutateSessionState) and blocks mid-mutation; a concurrent
// clearSessionState call must block until the writer releases, not run
// concurrently with it.
func TestClearSessionState_SerializesAgainstConcurrentMutation(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	t.Chdir(dir)

	s := &ManualCommitStrategy{}
	const sessionID = "race-session"
	require.NoError(t, s.saveSessionState(context.Background(), &SessionState{
		SessionID:  sessionID,
		BaseCommit: "abc123",
		StartedAt:  time.Now(),
	}))

	writerStarted := make(chan struct{})
	writerMayFinish := make(chan struct{})
	writerFinished := make(chan struct{})
	go func() {
		defer close(writerFinished)
		if err := MutateSessionState(context.Background(), sessionID, func(state *SessionState) error {
			close(writerStarted)
			<-writerMayFinish
			state.StepCount = 1
			return nil
		}); err != nil {
			t.Errorf("MutateSessionState: %v", err)
		}
	}()
	<-writerStarted // writer holds the gate now, mid-mutation

	clearStarted := make(chan struct{})
	clearReturned := make(chan struct{})
	go func() {
		defer close(clearReturned)
		close(clearStarted)
		if err := s.clearSessionState(context.Background(), sessionID); err != nil {
			t.Errorf("clearSessionState: %v", err)
		}
	}()
	// Wait until the goroutine is genuinely running before timing anything.
	// Without this, "clearReturned is not closed" is also satisfied by a
	// goroutine the scheduler never started, so the assertion below could
	// pass without the gate doing any work at all.
	<-clearStarted

	// clearSessionState must be blocked waiting for the writer's gate right
	// now. Before the fix (no locking at all in clearSessionState) it would
	// return almost immediately here, well within this window, proving the
	// race is real.
	select {
	case <-clearReturned:
		t.Fatal("clearSessionState returned while a concurrent MutateSessionState was still mid-mutation -- not serialized")
	case <-time.After(100 * time.Millisecond):
		// Expected: still blocked on the gate.
	}

	close(writerMayFinish)
	<-writerFinished
	<-clearReturned
}

// TestMutateSessionState_NestedCallsAreReentrant verifies that calling
// MutateSessionState from within an outer MutateSessionState callback
// doesn't deadlock. POSIX flock isn't reentrant across distinct FDs in the
// same process, so the gate's goroutine-ID ownership tracking has to skip
// the flock re-acquire on the inner call.
func TestMutateSessionState_NestedCallsAreReentrant(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	t.Chdir(dir)

	state := &SessionState{
		SessionID:  "ft-nested",
		BaseCommit: "deadbeef",
		StartedAt:  time.Now(),
	}
	require.NoError(t, SaveSessionState(context.Background(), state))

	done := make(chan struct{})
	go func() {
		defer close(done)
		err := MutateSessionState(context.Background(), "ft-nested", func(outer *SessionState) error {
			outer.LastPrompt = "outer"
			return MutateSessionState(context.Background(), "ft-nested", func(inner *SessionState) error {
				inner.ModelName = "inner"
				return nil
			})
		})
		assert.NoError(t, err)
	}()
	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("nested MutateSessionState deadlocked")
	}

	loaded, err := LoadSessionState(context.Background(), "ft-nested")
	require.NoError(t, err)
	require.NotNil(t, loaded)
	assert.Equal(t, "outer", loaded.LastPrompt)
	assert.Equal(t, "inner", loaded.ModelName)
}

// TestRecordFilesTouched_ParallelMergesAreSerialized verifies the file-lock
// in RecordFilesTouched: many concurrent callers, each merging a unique
// file, must all land in FilesTouched. Without the lock, parallel
// load → merge → save would lose updates and the final list would be missing
// entries (or have duplicates).
func TestRecordFilesTouched_ParallelMergesAreSerialized(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	t.Chdir(dir)

	state := &SessionState{
		SessionID:  "ft-parallel",
		BaseCommit: "deadbeef",
		StartedAt:  time.Now(),
	}
	require.NoError(t, SaveSessionState(context.Background(), state))

	const n = 20
	var wg sync.WaitGroup
	wg.Add(n)
	for i := range n {
		go func() {
			defer wg.Done()
			path := fmt.Sprintf("file-%02d.go", i)
			err := RecordFilesTouched(context.Background(), "ft-parallel", nil, []string{path}, nil)
			assert.NoError(t, err)
		}()
	}
	wg.Wait()

	loaded, err := LoadSessionState(context.Background(), "ft-parallel")
	require.NoError(t, err)
	require.NotNil(t, loaded)
	require.Len(t, loaded.FilesTouched, n, "every concurrent merge should be present")
}

